from schema import mcq

mcq(11,1,'پتانسیل عمل','شدت یک محرک پایدارِ مؤثر بر گیرندهٔ حسی را، در مدت برابر و محدودهٔ غیرآسیب‌زا، افزایش می‌دهیم. کدام مقایسهٔ پیام‌های نورون حسی با شیوهٔ معمول رمزکردن شدت بیشتر سازگارتر است؟',[
('بزرگ‌ترشدن نامحدود ارتفاع هر پتانسیل عمل','پتانسیل عمل از قانون همه یا هیچ پیروی می‌کند؛ شدت محرک با افزایش نامحدود دامنه رمز نمی‌شود.'),
('کاهش بسامد پیام‌ها به‌عنوان رمز شدت بیشتر','در شرایط گفته‌شده شدت بیشتر معمولاً با افزایش بسامد قابل رمزشدن است، نه کاهش آن.'),
('افزایش بسامد پتانسیل‌های عمل در محدودهٔ توان نورون','با رسیدن محرک به آستانه، دامنهٔ هر پتانسیل عمل تقریباً ثابت است؛ شدت بیشتر می‌تواند بسامد پیام‌ها را افزایش دهد.'),
('نصف‌شدن آستانهٔ هر پتانسیل عمل صرفاً به علت قوی‌ترشدن محرک','قوی‌ترشدن محرک به‌تنهایی به معنی نصف‌شدن آستانه نیست؛ رمز معمول شدت، تغییر بسامد است.')],2,'شدت محرک را با دامنهٔ پتانسیل عمل اشتباه نگیریم.')
mcq(11,1,'شیب پتانسیل عمل','نمودار پاسخ طبیعی آسه را نشان می‌دهد؛ P بخش صعودی و R بخش نزولی است. اگر پیش از تحریک، دارویی فقط بازشدن دریچه‌های سدیمی وابسته به ولتاژ را مهار کند، کدام پیش‌بینی مناسب‌تر است؟',[
('ایجاد صعود طبیعی P مختل می‌شود، چون ورود سریع سدیم محدود شده است','صعود طبیعی به بازشدن دریچه‌های سدیمی و ورود سدیم وابسته است؛ مهار آن‌ها می‌تواند ایجاد پتانسیل عمل را مختل کند.'),
('P حتماً بلندتر می‌شود، چون سدیم بیشتری وارد می‌شود','مهار بازشدن دریچهٔ سدیمی ورود سریع سدیم را محدود می‌کند، نه بیشتر.'),
('تنها R مختل می‌شود و P با ورود پتاسیم کاملاً طبیعی می‌ماند','صعود P عمدتاً به ورود سدیم مربوط است؛ دارو مستقیماً همین مرحله را هدف گرفته است.'),
('فقط پمپ سدیم‌ـ‌پتاسیم مهار شده و بازشدن دریچه‌ها تغییری نکرده است','فرض سؤال مهار دریچهٔ وابسته به ولتاژ است؛ پمپ و دریچه دو سازوکار متفاوت‌اند.')],0,'هدف دارو را از پمپ و از دریچهٔ یون دیگر جدا کنیم.',image='diagrams/neuron.png')
mcq(11,1,'سیناپس شیمیایی','دارویی آزادشدن ناقل عصبی از پایانهٔ نورون پیش‌سیناپسی را متوقف می‌کند؛ پتانسیل عمل همچنان به پایانه می‌رسد. کدام نتیجه مستقیم‌تر است؟',[
('غلظت ناقل در شکاف سیناپسی حتماً بیشتر می‌شود','با توقف آزادسازی، افزایش الزامی غلظت ناقل در شکاف نتیجه نمی‌شود و پیام‌رسانی کم می‌شود.'),
('دیگر هیچ پتانسیل عملی نمی‌تواند در هیچ نورونی ایجاد شود','اثر موضعی بر آزادسازی ناقل را نمی‌توان به توقف پیام در همهٔ نورون‌ها تعمیم داد.'),
('رسیدن پتانسیل عمل به پایانه به‌تنهایی پاسخ پس‌سیناپسی طبیعی را تضمین می‌کند','در سیناپس شیمیایی باید ناقل نیز آزاد و به گیرنده متصل شود؛ رسیدن پیام به پایانه کافی نیست.'),
('اثر شیمیایی این پایانه بر یاختهٔ پس‌سیناپسی کاهش می‌یابد','رسیدن پتانسیل عمل کافی نیست؛ در سیناپس شیمیایی باید ناقل آزاد شود تا بر گیرندهٔ پس‌سیناپسی اثر بگذارد.')],3,'رسیدن پیام به پایانه و انتقال آن در سیناپس دو مرحله‌اند.')
mcq(11,1,'انعکاس و دستگاه مرکزی','دست فرد پیش از آگاهی کامل از درد، از جسم داغ دور می‌شود. کدام برداشت درست است؟',[
('چون پاسخ سریع است، هیچ بخش دستگاه عصبی مرکزی دخالت ندارد','نخاع بخشی از دستگاه عصبی مرکزی است و در انعکاس دورکردن دست نقش دارد.'),
('مدار نخاعی می‌تواند پاسخ را آغاز کند و پیام درد نیز به مغز برسد','آغاز پاسخ انعکاسی به پردازش نخاعی وابسته است و این امر مانع رسیدن پیام حسی به مغز و ادراک درد نیست.'),
('نورون حرکتی پیام را از پوست به نخاع می‌برد','پیام از گیرندهٔ پوست به دستگاه مرکزی با نورون حسی می‌رود؛ حرکتی به ماهیچه فرمان می‌برد.'),
('برای آغاز پاسخ نخاعی، ادراک آگاهانهٔ درد در قشر مغز شرط لازم است','انعکاس دورکردن دست می‌تواند پیش از آگاهی کامل آغاز شود؛ این ویژگی با لزوم ادراک آگاهانه ناسازگار است.')],1,'غیرارادی‌بودن به معنی نبود دستگاه عصبی مرکزی نیست.')

mcq(11,2,'تطابق عدسی','چشم سالم از نگاه‌کردن به دوردست به خواندن نوشتهٔ نزدیک می‌پردازد. کدام تغییر به تشکیل تصویر واضح روی شبکیه کمک می‌کند؟',[
('کاهش انحنای عدسی برای افزایش قدرت همگرایی','کاهش انحنا قدرت همگرایی را افزایش نمی‌دهد؛ دید نزدیک به عدسی محدب‌تر نیاز دارد.'),
('استراحت ماهیچهٔ مژگانی و افزایش کشش تارهای آویزی','این تغییر عدسی را کم‌انحناتر و برای دید دور مناسب‌تر می‌کند، نه تطابق برای نزدیک.'),
('انقباض ماهیچهٔ مژگانی، کاهش کشش تارها و محدب‌ترشدن عدسی','در دید نزدیک، انقباض ماهیچهٔ مژگانی کشش تارهای آویزی را کم می‌کند و عدسی با انحنای بیشتر نور را بیشتر همگرا می‌کند.'),
('افزایش کشش تارهای آویزی و محدب‌ترشدن عدسی','افزایش کشش عدسی را مسطح‌تر می‌کند؛ این گزینه رابطهٔ کشش و انحنا را وارونه کرده است.')],2,'انقباض ماهیچهٔ مژگانی را با افزایش کشش تارهای آویزی یکی ندانیم.')
mcq(11,2,'بینایی و گیرنده‌ها','فرد در نور بسیار کم شکل کلی یک شیء را می‌بیند، اما رنگ آن را خوب تشخیص نمی‌دهد. کدام توضیح سازگارتر است؟',[
('گیرنده‌های استوانه‌ای در نور کم کارآمدترند و دید رنگی عمدتاً به مخروطی‌ها وابسته است','استوانه‌ای‌ها حساسیت بیشتری در نور کم دارند، ولی تشخیص رنگ عمدتاً کار مخروطی‌هاست.'),
('مخروطی‌ها تنها گیرنده‌های فعال در تاریکی‌اند','در نور کم نقش استوانه‌ای‌ها بیشتر است؛ مخروطی‌ها برای کار مناسب به نور بیشتری نیاز دارند.'),
('دید رنگی در عدسی ساخته می‌شود و به شبکیه مربوط نیست','عدسی نور را متمرکز می‌کند؛ گیرنده‌های نور و تمایز رنگ در شبکیه‌اند.'),
('استوانه‌ای‌ها هر کدام همهٔ رنگ‌ها را با دقت بیشتری از مخروطی‌ها تفکیک می‌کنند','استوانه‌ای‌ها برای دید کم‌نور حساس‌اند، اما تفکیک رنگ به شکل مخروطی‌ها کار آن‌ها نیست.')],0,'حساسیت به نور و توان تشخیص رنگ یک ویژگی واحد نیستند.')
mcq(11,2,'شنوایی و تعادل','آسیب محدود به مجاری نیم‌دایره‌ای گوش درونی، بدون آسیب به حلزون، نخست کدام کارکرد را بیشتر تهدید می‌کند؟',[
('تقویت صدا توسط استخوانچه‌های گوش میانی','استخوانچه‌ها در گوش میانی‌اند؛ مجاری نیم‌دایره‌ای محل تقویت مکانیکی صدا نیستند.'),
('جلوگیری از ورود گردوغبار به مجرای شنوایی بیرونی','این حفاظت به ساختارهای گوش بیرونی مربوط است.'),
('دریافت بسامدهای صوتی توسط گیرنده‌های حلزون','در فرض سؤال حلزون سالم است؛ نقش مستقیم مجاری نیم‌دایره‌ای تعادل است، نه تفکیک بسامد صوتی.'),
('دریافت اطلاعات مربوط به تغییرات حرکت چرخشی سر','مجاری نیم‌دایره‌ای در تعادل و دریافت تغییر حرکت چرخشی سر نقش دارند؛ حلزون به شنوایی مربوط است.')],3,'همهٔ ساختارهای گوش درونی وظیفهٔ شنوایی ندارند.')
mcq(11,2,'سازش گیرنده‌ها','پس از مدتی، فرد بوی ثابت و بی‌خطر اتاق را کمتر حس می‌کند؛ ورود بوی تازه را باز هم تشخیص می‌دهد. این مشاهده بیشتر چه چیزی را نشان می‌دهد؟',[
('همهٔ مولکول‌های بو از اتاق حذف شده‌اند','کم‌شدن احساس بو به‌تنهایی نبود مولکول بو را ثابت نمی‌کند.'),
('پاسخ به محرک یکنواخت می‌تواند کاهش یابد، بدون آنکه کل توان حس‌کردن از بین برود','سازش حسی پاسخ به محرک مداوم را کاهش می‌دهد؛ پاسخ به محرک تازه می‌تواند برقرار بماند.'),
('کم‌شدن احساس ثابت می‌کند همهٔ گیرنده‌های بویایی برای همیشه بی‌پاسخ شده‌اند','تشخیص بوی تازه با ازکارافتادن دائمی همهٔ گیرنده‌ها سازگار نیست.'),
('گیرندهٔ حسی به محرک یکنواخت الزاماً پاسخ فزاینده و بدون محدودیت می‌دهد','در مثال، پاسخ به محرک یکنواخت کاهش یافته است؛ همهٔ گیرنده‌ها پاسخ فزایندهٔ نامحدود ندارند.')],1,'کاهش احساس یک محرک با حذف محرک یا نابودی حس یکسان نیست.')

mcq(11,3,'انقباض سارکومر','در انقباض معمول یک سارکومر، فاصلهٔ دو خط Z کمتر می‌شود. کدام تغییر با نظریهٔ لغزش رشته‌ها سازگار است؟',[
('هر رشتهٔ اکتین از دو انتها کوتاه می‌شود','رشته‌های اکتین هنگام لغزش کوتاه نمی‌شوند؛ جایگاه نسبی آن‌ها تغییر می‌کند.'),
('میزان هم‌پوشانی رشته‌های نازک و ضخیم کمتر می‌شود','در انقباض معمول، هم‌پوشانی بیشتر می‌شود و کاهش آن با کوتاه‌شدن سارکومر سازگار نیست.'),
('با ثبات طول رشته‌ها، هم‌پوشانی آن‌ها بیشتر می‌شود','کوتاه‌شدن سارکومر حاصل لغزش و افزایش هم‌پوشانی رشته‌هاست، نه کوتاه‌شدن خود رشته‌ها.'),
('دو خط Z از هم دورتر می‌شوند','در انقباض سارکومر خطوط Z به هم نزدیک‌تر می‌شوند.')],2,'کوتاه‌شدن واحد ماهیچه‌ای به معنی کوتاه‌شدن رشته‌های پروتئینی نیست.')
mcq(11,3,'ماهیچه‌های مخالف','برای خم‌کردن ساعد و سپس بازکردن آن، چرا کار هماهنگ دو ماهیچهٔ مخالف لازم است؟',[
('ماهیچه با انقباض می‌کشد و بازگشت جهت حرکت به کشش ماهیچهٔ مخالف نیاز دارد','ماهیچهٔ اسکلتی نیروی کششی ایجاد می‌کند؛ ماهیچه‌های مخالف حرکت استخوان را در دو جهت ممکن می‌سازند.'),
('هر ماهیچه با انقباض هم می‌کشد و هم استخوان را در جهت مخالف هل می‌دهد','انقباض ماهیچه نیروی کششی ایجاد می‌کند و برای هل‌دادن در جهت مخالف عمل نمی‌کند.'),
('هر دو ماهیچه باید در همهٔ لحظه‌ها دقیقاً بیشترین انقباض را داشته باشند','حرکت به تنظیم فعالیت دو ماهیچه وابسته است؛ بیشینه‌بودن همیشگی هر دو حرکت طبیعی ایجاد نمی‌کند.'),
('یک ماهیچه با شل‌شدن فعالانه همان نیروی کششی انقباض را در جهت مقابل تولید می‌کند','شل‌شدنِ ماهیچه نیروی کششی فعالِ معکوس ایجاد نمی‌کند؛ ماهیچهٔ مخالف جهت مقابل را فراهم می‌کند.')],0,'ماهیچهٔ اسکلتی فعالانه می‌کشد؛ استخوان را هل نمی‌دهد.')
mcq(11,3,'بافت استخوان','کاهش شدید مواد معدنی استخوان، در حالی که بخش آلی آن باقی است، بیشتر کدام ویژگی را کم می‌کند؟',[
('انعطاف‌پذیری به علت حذف کامل کلاژن','در فرض سؤال بخش آلی باقی است؛ حذف کلاژن نتیجهٔ کاهش مواد معدنی نیست.'),
('مقاومت کششی فقط به علت نابودی رشته‌های آلی','بخش آلی در فرض سؤال حفظ شده و علت اصلی تغییر، کاهش جزء معدنی است.'),
('قابلیت خم‌شدن با افزایش قطعی سختی','کاهش مواد معدنی معمولاً سختی را کم و انعطاف نسبی را بیشتر می‌کند؛ افزایش سختی نتیجهٔ مورد انتظار نیست.'),
('سختی و مقاومت استخوان در برابر فشار','بخش معدنی به سختی و مقاومت فشاری استخوان کمک می‌کند؛ بخش آلی در انعطاف‌پذیری و مقاومت کششی نقش دارد.')],3,'نقش بخش معدنی و رشته‌های آلی استخوان را تفکیک کنیم.')
mcq(11,3,'واحد حرکتی','برای افزایش نیروی یک ماهیچهٔ اسکلتی، فعال‌شدن واحدهای حرکتی بیشتری چه اثری دارد؟',[
('تعداد تارهای فعال کمتر می‌شود، ولی واحدهای بیشتری به کار می‌افتند','فراخوانی واحدهای بیشتر معمولاً تعداد تارهای درگیر را افزایش می‌دهد؛ کاهش آن از تعریف واحد حرکتی نتیجه نمی‌شود.'),
('تعداد تارهای شرکت‌کننده در انقباض می‌تواند بیشتر شود','هر واحد حرکتی شامل یک نورون حرکتی و تارهای تحت کنترل آن است؛ فراخوانی واحدهای بیشتر شمار تارهای فعال را افزایش می‌دهد.'),
('یک نورون حرکتی معمولاً تنها بخشی از یک تار را منقبض و بقیه را مستقل نگه می‌دارد','واحد حرکتی یک نورون و تارهای تحت کنترل آن است؛ فرض تقسیم مستقل یک تار میان پاسخ‌های جزئی تعریف آن نیست.'),
('به‌کارگرفتن واحدهای بیشتر الزاماً نیروی کل را کم می‌کند','در شرایط مشابه، افزایش تعداد تارهای فعال می‌تواند نیرو را بیشتر کند، نه الزاماً کمتر.')],1,'افزایش نیروی کل ماهیچه را فقط تغییر شدت پاسخ یک تار ندانیم.')

mcq(11,4,'گیرندهٔ هورمون','دو نوع یاخته در تماس با یک هورمون خون‌اند، اما فقط یکی پاسخ اختصاصی می‌دهد. کدام علت محتمل‌تر است؟',[
('فقط یاختهٔ بی‌پاسخ حتماً در تماس با خون قرار گرفته است','فرض سؤال تماس هر دو نوع با هورمون است؛ تفاوت پاسخ را نباید صرفاً به نرسیدن هورمون نسبت داد.'),
('هورمون در همهٔ یاخته‌ها باید واکنش یکسان ایجاد کند','پاسخ هورمونی به گیرنده و توان پاسخ‌دهی یاخته وابسته است، پس الزاماً یکسان نیست.'),
('یاختهٔ پاسخ‌دهنده گیرندهٔ مناسب آن هورمون را دارد','وجود گیرندهٔ اختصاصی شرط اثرگذاری هورمون بر یاختهٔ هدف است؛ تماس خونی به‌تنهایی کافی نیست.'),
('هورمون فقط از راه مجرای غده به همان یاخته می‌رسد','هورمون درون‌ریز از راه خون توزیع می‌شود؛ مجرای اختصاصی شرط رسیدن آن نیست.')],2,'قرارگرفتن در برابر هورمون با هدف‌بودن یاخته یکسان نیست.')
mcq(11,4,'تنظیم قند خون','پس از وعدهٔ غذایی پرکربوهیدرات، افزایش انسولین در فرد سالم چگونه به بازگشت قند خون کمک می‌کند؟',[
('با تسهیل ورود گلوکز به برخی یاخته‌ها و افزایش ذخیره‌سازی آن','انسولین برداشت گلوکز در یاخته‌های هدف و ذخیره‌سازی، از جمله ساخت گلیکوژن، را تقویت می‌کند و قند خون را پایین می‌آورد.'),
('با تبدیل همهٔ گلیکوژن کبد به گلوکز و رهاکردن آن در خون','این جهت اثر، قند خون را افزایش می‌دهد و اثر معمول انسولین نیست.'),
('با مهار ذخیره‌سازی گلوکز در یاخته‌های هدف','مهار ذخیره‌سازی با اثر معمول انسولین بر تقویت ذخیره‌سازی گلوکز سازگار نیست.'),
('با کاهش برداشت گلوکز از خون توسط یاخته‌های هدف','کاهش برداشت قند را در خون نگه می‌دارد؛ انسولین در یاخته‌های اثرپذیر برداشت را افزایش می‌دهد.')],0,'جهت اثر انسولین و گلوکاگون را وارونه نکنیم.')
mcq(11,4,'بازخورد منفی تیروئید','اگر مقدار هورمون‌های تیروئیدی خون در فرد سالم بالا رود، بازخورد منفی معمولاً ترشح محرک تیروئید از هیپوفیز را چگونه تغییر می‌دهد؟',[
('به‌طور نامحدود افزایش می‌دهد','افزایش نامحدود با بازخورد مثبت سازگار است؛ محور تیروئید بازخورد منفی دارد.'),
('ترشح آن فقط با تغییر ید غذا تغییر می‌کند و به هورمون تیروئیدی پاسخ نمی‌دهد','ید در ساخت هورمون اهمیت دارد، اما مسیر بازخوردی نیز ترشح محرک تیروئید را تنظیم می‌کند.'),
('به علت استقلال کامل دو غده، تغییری در مسیر تنظیم رخ نمی‌دهد','هیپوفیز و تیروئید از راه بازخورد هورمونی مرتبط‌اند؛ افزایش هورمون می‌تواند ترشح بالادست را کم کند.'),
('ترشح آن را کاهش می‌دهد و تحریک تیروئید کمتر می‌شود','افزایش فرآوردهٔ نهایی با مهار مسیر بالادست، از تحریک بیشتر تیروئید جلوگیری می‌کند.')],3,'بازخورد منفی پاسخ را در جهت کاهش تغییر اولیه تنظیم می‌کند.')
mcq(11,4,'پیام عصبی و درون‌ریز','در خطر ناگهانی، پیام عصبی به غدهٔ فوق‌کلیه می‌رسد و بخش مرکزی آن هورمون به خون می‌ریزد. این رویداد چه چیزی را نشان می‌دهد؟',[
('دستگاه عصبی و درون‌ریز هیچ ارتباطی ندارند','رسیدن پیام عصبی به غده و تحریک ترشح، نمونهٔ ارتباط این دو دستگاه است.'),
('یک پاسخ می‌تواند با هماهنگی مسیر عصبی و هورمونی شکل بگیرد','پیام عصبی می‌تواند ترشح هورمون را آغاز کند؛ هورمون نیز از راه خون بر یاخته‌های هدف اثر می‌گذارد.'),
('هورمون‌ها برای اثرگذاری باید حتماً به ناقل عصبی تبدیل شوند','هورمون از راه گیرندهٔ مناسب عمل می‌کند و تبدیل به ناقل عصبی شرط عمومی اثر آن نیست.'),
('همهٔ پیام‌های هورمونی از راه آسه به هدف می‌رسند','هورمون‌های درون‌ریز از راه خون می‌رسند؛ آسه مسیر هدایت پیام عصبی است.')],1,'دو شیوهٔ پیام‌رسانی می‌توانند در یک پاسخ هماهنگ شرکت کنند.')

mcq(11,5,'ایمنی فعال و غیرفعال','فردی یک‌بار واکسن و فرد دیگری پادتن آماده دریافت می‌کند. کدام تفاوت درست‌تر است؟',[
('پادتن آماده همواره حافظهٔ اختصاصی پایدار در بدن گیرنده می‌سازد','پادتن آماده ایمنی غیرفعال می‌دهد و به‌خودی‌خود ساخت یاختهٔ خاطره در گیرنده را تضمین نمی‌کند.'),
('واکسن فقط با نابودکردن همهٔ لنفوسیت‌ها اثر می‌کند','واکسن پاسخ اختصاصی و حافظه را تحریک می‌کند، نه نابودی همهٔ لنفوسیت‌ها.'),
('واکسن می‌تواند خاطره بسازد؛ پادتن آماده حفاظت موقت می‌دهد','در ایمنی فعال، بدن پاسخ و خاطره می‌سازد؛ در ایمنی غیرفعال، پادتن بیرونی مستقیماً حفاظت موقت ایجاد می‌کند.'),
('هیچ‌کدام به دفاع اختصاصی ارتباط ندارند','واکسن و پادتن هر دو با ایمنی اختصاصی مرتبط‌اند، هرچند شیوهٔ ایجاد حفاظت متفاوت است.')],2,'داشتن پادتن در خون الزاماً به معنی ساخته‌شدن حافظه در همان فرد نیست.')
mcq(11,5,'التهاب و دفاع غیراختصاصی','پس از خراش پوست، قرمزی و تورم موضعی پدید می‌آید. کدام توضیح با التهاب سازگارتر است؟',[
('تغییر رگ‌ها و افزایش دسترسی سلول‌های دفاعی به ناحیهٔ آسیب','گشادشدن رگ‌ها و افزایش نفوذپذیری در التهاب به رسیدن عوامل دفاعی و خروج مایع کمک می‌کند.'),
('تولید گویچه‌های سرخ اختصاصی برای هر باکتری','گویچهٔ سرخ سلول پاسخ اختصاصی به هر باکتری نیست.'),
('بسته‌شدن همیشگی تمام مویرگ‌های ناحیه بدون ورود سلول دفاعی','التهاب معمولاً با افزایش خون‌رسانی و دسترسی دفاعی همراه است، نه قطع همیشگی آن.'),
('ساخته‌شدن حافظهٔ اختصاصی توسط هر یاختهٔ پوست','همهٔ یاخته‌های پوست یاختهٔ خاطرهٔ ایمنی نمی‌سازند؛ التهاب بخشی از دفاع غیراختصاصی است.')],0,'نشانه‌های التهاب را با سازوکار اختصاصی خاطرهٔ ایمنی یکی ندانیم.')
mcq(11,5,'پادتن و پادگن','پادتن تولیدشده علیه پادگن A به پادگن متفاوت B متصل نمی‌شود. این مشاهده بیشتر کدام ویژگی را نشان می‌دهد؟',[
('هر پادتن به هر ماده‌ای با قدرت یکسان متصل می‌شود','اتصال پادتن اختصاصی است و شکل جایگاه اتصال اهمیت دارد.'),
('پادگن و پادتن یک مولکول با دو نام‌اند','پادگن هدف شناسایی و پادتن مولکول دفاعی متصل‌شونده به آن است.'),
('پادتن از جنس نشاسته و بی‌ساختار است','پادتن پروتئین است و ساختار آن در اتصال اهمیت دارد.'),
('تناسب ساختاری جایگاه اتصال با پادگن اهمیت دارد','پادتن‌ها جایگاه‌های اتصال اختصاصی دارند؛ تفاوت ساختار پادگن می‌تواند مانع اتصال مناسب شود.')],3,'اختصاصی‌بودن را به معنای یکسان‌بودن همهٔ مولکول‌های دفاعی نگیریم.')
mcq(11,5,'لنفوسیت و یاختهٔ آلوده','در عفونت ویروسی، کدام مقایسه میان لنفوسیت B فعال و T کشنده مناسب است؟',[
('هر دو فقط با بلعیدن مستقیم ویروس خارج‌یاخته‌ای عمل می‌کنند','بلعیدن عمومی عامل اصلی این دو نیست؛ B به تولید پادتن و T کشنده به نابودی یاختهٔ آلوده مربوط است.'),
('پادتن می‌تواند بیرون یاخته اثر کند؛ T کشنده یاختهٔ آلوده را هدف می‌گیرد','B فعال می‌تواند به یاختهٔ پادتن‌ساز تبدیل شود؛ T کشنده با شناسایی هدف مناسب به نابودی یاختهٔ آلوده کمک می‌کند.'),
('لنفوسیت B هیچ ارتباطی با پروتئین‌های دفاعی ندارد','پادتن‌ها پروتئین‌اند و از یاخته‌های پادتن‌سازِ مشتق از B ساخته می‌شوند.'),
('T کشنده فقط پادتن آزاد ترشح می‌کند و هرگز یاختهٔ آلوده را هدف نمی‌گیرد','ترشح پادتن کار اصلی یاخته‌های پادتن‌ساز است؛ T کشنده با هدف‌گیری یاختهٔ آلوده نقش متفاوتی دارد.')],1,'عامل بیرون یاخته و یاختهٔ آلوده هدف‌های یکسانی نیستند.')

mcq(11,6,'فام‌تن و مقدار دنا','یاخته‌ای پیکری با ۲n=۸ پس از پایان همانندسازی و پیش از جدایی کروماتیدهای خواهری قرار دارد. کدام شمارش درست است؟',[
('۱۶ فام‌تن و ۸ مولکول دنا','پیش از جدایی، تعداد فام‌تن بر پایهٔ سانترومر ۸ است و هر فام‌تن دو مولکول دنا دارد.'),
('۸ فام‌تن و ۸ مولکول دنا','همانندسازی تعداد مولکول‌های دنا را دو برابر کرده است؛ هر فام‌تن دو کروماتید دارد.'),
('۸ فام‌تن و ۱۶ مولکول دنا','تعداد سانترومرها و فام‌تن‌ها هنوز ۸ است؛ ۱۶ کروماتید هر کدام یک مولکول دنا دارند.'),
('۴ فام‌تن و ۱۶ مولکول دنا','کاهش مجموعهٔ فام‌تنی رخ نداده و یاخته همچنان ۸ فام‌تن دارد.')],2,'شمار فام‌تن را از شمار مولکول دنا جدا کنیم.')
mcq(11,6,'چرخهٔ یاخته و دنا','نمودار، چرخهٔ طبیعی یک یاخته را نشان می‌دهد؛ A پیش از همانندسازی، B پس از آن و C یک دختر پس از میتوز است. در آزمایش دوم، پیش از A ماده‌ای مانع ساخت دنای تازه می‌شود. کدام تغییر نخستین، مستقیم‌تر انتظار می‌رود؟',[
('افزایش مقدار دنا از سطح A به سطح B رخ نمی‌دهد','افزایش A به B به همانندسازی نیاز دارد؛ جلوگیری از ساخت دنا مستقیماً این افزایش را مختل می‌کند.'),
('مقدار دنا ابتدا از ۲ به ۸ می‌رسد','مهار ساخت دنای تازه با افزایش چهاربرابری سازگار نیست.'),
('کاهش طبیعی B به C حتماً بدون رسیدن به B دقیقاً تکرار می‌شود','با مختل‌شدن همانندسازی، نمی‌توان ادامهٔ طبیعی چرخه و تقسیم را تضمین کرد.'),
('چون ساخت دنا مهار شده، فقط مقدار پروتئین و نه منحنی دنا تغییر می‌کند','هدف مستقیم ماده ساخت دناست و افزایش مقدار دنا را مختل می‌کند.')],0,'توالی زمانی منحنی را با محل اثر یک مداخله مرتبط کنیم.',image='diagrams/cell_dna.png')
mcq(11,6,'جدایی در میوز','در میوز طبیعی، همتاها در تقسیم نخست و کروماتیدهای خواهری در تقسیم دوم جدا می‌شوند. اگر یاختهٔ آغازین ۲n=۶ باشد، هر فرآوردهٔ نهایی معمولاً چه دارد؟',[
('۶ فام‌تن دوکروماتیدی','محصول نهایی میوز یک مجموعهٔ ۳تایی دارد و کروماتیدهای خواهری نیز جدا شده‌اند.'),
('۳ جفت فام‌تن همتا','محصول طبیعی میوز از هر جفت همتا یک عضو دارد، نه هر سه جفت کامل.'),
('۱۲ فام‌تن تک‌کروماتیدی','دو تقسیم میوز مجموعهٔ فام‌تنی را نصف می‌کند و چنین افزایش فام‌تنی رخ نمی‌دهد.'),
('۳ فام‌تن تک‌کروماتیدی','نصف‌شدن تعداد مجموعه‌ها در میوز نخست و جدایی خواهری در میوز دوم، محصول n=۳ با فام‌تن تک‌کروماتیدی می‌دهد.')],3,'دو تقسیم میوز را با دو بار همانندسازی اشتباه نگیریم.')
mcq(11,6,'میوز و تنوع','دو گامت حاصل از میوز یک فرد می‌توانند ترکیب متفاوتی از فام‌تن‌های مادری و پدری او داشته باشند. کدام فرایند مستقیماً این تنوع را ایجاد می‌کند؟',[
('همانندسازی دوبارهٔ دنا بین میوز اول و دوم','بین دو تقسیم میوز همانندسازی دوبارهٔ دنا انجام نمی‌شود.'),
('آرایش مستقل جفت‌های همتا در تقسیم نخست','جهت‌گیری مستقل جفت‌های همتا سبب می‌شود ترکیب‌های متفاوتی از فام‌تن‌های مادری و پدری به گامت‌ها برسد.'),
('یکسان‌شدن همهٔ دگره‌ها در یاختهٔ آغازین','یکسان‌شدن همهٔ دگره‌ها منشأ تفاوت ترکیب گامت‌ها نیست.'),
('حذف همیشگی همهٔ فام‌تن‌های پدری','میوز طبیعی حذف انحصاری همهٔ فام‌تن‌های یک والد نیست.')],1,'گامت‌ها الزاماً نسخه‌های ژنتیکی یکسان نیستند.')

mcq(11,7,'چرخهٔ تخمدان و رحم','در چرخهٔ طبیعی بدون بارداری، تحلیل جسم زرد با افت پروژسترون همراه می‌شود. کدام پیامد با این افت ارتباط دارد؟',[
('حفظ دائمی جسم زرد بدون نیاز به پیام بارداری','در چرخهٔ بدون بارداری جسم زرد تحلیل می‌رود؛ حفظ دائمی با فرض سؤال ناسازگار است.'),
('افزایش حمایت پروژسترونی از درون‌شامه با افت همین هورمون','افت پروژسترون حمایت آن را بیشتر نمی‌کند و می‌تواند به ریزش درون‌شامه کمک کند.'),
('کاهش حمایت هورمونی از درون‌شامهٔ رحم و آغاز ریزش آن','پروژسترون جسم زرد به حفظ درون‌شامه کمک می‌کند؛ افت هورمون‌های تخمدانی با قاعدگی ارتباط دارد.'),
('افزایش همیشگی ضخامت درون‌شامه بدون هیچ ریزش','بدون بارداری و با افت هورمون‌ها، حفظ دائمی درون‌شامه انتظار نمی‌رود.')],2,'تغییر تخمدان و تغییر رحم را رویدادهای کاملاً جدا ندانیم.')
mcq(11,7,'مسیر اسپرم','برای ردیابی اسپرم از محل ساخت تا ورود به میزراه، کدام ترتیب درست‌تر است؟',[
('لولهٔ اسپرم‌ساز → اپیدیدیم → زامه‌بر → میزراه','اسپرم در لوله‌های اسپرم‌ساز ساخته می‌شود، در اپیدیدیم مراحل بلوغ و ذخیره را می‌گذراند و از زامه‌بر به مسیر خروج می‌رود.'),
('اپیدیدیم → تخمدان → زامه‌بر → میزراه','تخمدان بخشی از دستگاه تولیدمثل مرد نیست و اسپرم در اپیدیدیم ساخته نمی‌شود.'),
('پروستات → لوله‌های اسپرم‌ساز → اپیدیدیم → میزنای','پروستات ترشح کمکی دارد؛ میزنای مسیر انتقال ادرار از کلیه است، نه مسیر طبیعی اسپرم.'),
('میزراه → زامه‌بر → اپیدیدیم → لوله‌های اسپرم‌ساز','این ترتیب خلاف جهت معمول حرکت اسپرم از محل ساخت به خروج است.')],0,'محل ساخت اسپرم را با غده‌های سازندهٔ مایع منی یکی ندانیم.')
mcq(11,7,'لقاح و لانه‌گزینی','کدام مقایسه دربارهٔ لقاح و لانه‌گزینی طبیعی انسان درست است؟',[
('هر دو رویداد معمولاً درون تخمدان انجام می‌شوند','لقاح معمولاً در لولهٔ رحم و لانه‌گزینی در درون‌شامهٔ رحم رخ می‌دهد.'),
('لانه‌گزینی باید پیش از تشکیل تخم رخ دهد','لانه‌گزینی مربوط به جنین آغازین پس از لقاح و چند تقسیم است.'),
('تخم برای رسیدن به رحم هیچ تقسیمی انجام نمی‌دهد','جنین در مسیر به رحم تقسیمات آغازین را می‌گذراند.'),
('لقاح در لولهٔ رحم و لانه‌گزینی بعدتر در درون‌شامه است','این دو رویداد هم در زمان و هم در محل متفاوت‌اند؛ جنین پس از تقسیمات آغازین در رحم مستقر می‌شود.')],3,'محل برخورد گامت‌ها را با محل استقرار جنین یکی ندانیم.')
mcq(11,7,'جفت و تبادل','در بارداری طبیعی، خون مادر و جنین در جفت معمولاً مستقیماً در یک رگ مشترک مخلوط نمی‌شوند. بااین‌حال اکسیژن می‌تواند منتقل شود، زیرا:',[
('تنها راه انتقال اکسیژن مخلوط‌شدن کامل دو خون است','گازها می‌توانند از سد نازک تبادل عبور کنند، بی‌آنکه دو خون کاملاً مخلوط شوند.'),
('مواد می‌توانند از سطح تبادل میان دو گردش عبور کنند','جفت سطح نزدیکی دو گردش و تبادل انتخابی مواد است؛ عبور ماده با مخلوط‌شدن مستقیم کل خون یکسان نیست.'),
('خون جنین فاقد هر نوع یاخته است','خون جنین دارای یاخته است؛ تبادل جفتی به بی‌یاخته‌بودن خون وابسته نیست.'),
('اکسیژن فقط با ورود کامل گویچه‌های سرخ مادر به خون جنین منتقل می‌شود','انتقال اکسیژن به عبور کامل گویچه‌ها وابسته نیست؛ مولکول اکسیژن می‌تواند از سطح تبادل عبور کند.')],1,'تبادل ماده را با اشتراک مستقیم رگ‌های دو فرد یکی ندانیم.')

mcq(11,8,'لقاح مضاعف','در یک نهاندانهٔ دولاد با گامت‌های طبیعی، یکی از دو زامه با تخم‌زا و دیگری با یاختهٔ مرکزی دارای دو هستهٔ قطبی آمیزش می‌یابد. فرآورده‌ها معمولاً به‌ترتیب چه لادی دارند؟',[
('تک‌لاد و دولاد','تخم‌زا و زامه هر دو n هستند و تخم ۲n می‌شود؛ فرآوردهٔ دوم معمولاً ۳n است.'),
('سه‌لاد و تک‌لاد','سه‌لادی به فرآوردهٔ آمیزش زامه با دو هستهٔ قطبی مربوط است، نه تخم.'),
('دولاد و سه‌لاد','آمیزش n+n تخم دولاد و آمیزش n+n+n هستهٔ آندوسپرم سه‌لاد را پدید می‌آورد.'),
('هر دو چهارلاد','در حالت معمول، جمع مجموعه‌های شرکت‌کننده به‌ترتیب دو و سه است، نه چهار.')],2,'دو آمیزش لقاح مضاعف، فرآورده‌هایی با لادی متفاوت می‌سازند.')
mcq(11,8,'گرده‌افشانی و لقاح','دانهٔ گرده روی کلالهٔ سازگار قرار گرفته است، اما رشد لولهٔ گرده متوقف می‌شود. کدام نتیجه درست‌تر است؟',[
('گرده‌افشانی رخ داده، ولی رسیدن زامه‌ها و لقاح می‌تواند مختل شود','قرارگیری گرده بر کلاله گرده‌افشانی است؛ لقاح به رشد لوله و رساندن زامه‌ها به کیسهٔ رویانی نیاز دارد.'),
('صرف رسیدن گرده به کلاله ثابت می‌کند تخم تشکیل شده است','گرده‌افشانی با آمیزش گامت‌ها یکسان نیست و تشکیل تخم را تضمین نمی‌کند.'),
('لولهٔ گرده از دیوارهٔ آوند چوبی ساخته می‌شود','لولهٔ گرده از یاختهٔ رویشی دانهٔ گرده رشد می‌کند، نه از آوند چوبی.'),
('تشکیل پوستهٔ گرده به‌تنهایی جای انتقال زامه به تخم‌زا را می‌گیرد','پوستهٔ گرده نقش انتقال گامت را جایگزین نمی‌کند؛ برای لقاح باید زامه به یاختهٔ مناسب برسد.')],0,'گرده‌افشانی مرحلهٔ انتقال گرده است، نه خود لقاح.')
mcq(11,8,'دانه و میوه','در گل معمول پس از لقاح، دیوارهٔ تخمدان و پوشش تخمک به‌ترتیب در ساخت کدام بخش‌ها نقش عمده دارند؟',[
('پوستهٔ دانه و دیوارهٔ میوه','این گزینه دو منشأ را جابه‌جا کرده است؛ دیوارهٔ تخمدان دیوارهٔ میوه و پوشش تخمک پوستهٔ دانه می‌سازد.'),
('دیوارهٔ میوه و جنین','بخش نخست درست است، اما جنین از تخم پدید می‌آید، نه از پوشش تخمک.'),
('آندوسپرم و پوستهٔ دانه','بخش دوم درست است، اما آندوسپرم از فرآوردهٔ لقاح زامه با یاختهٔ مرکزی پدید می‌آید، نه دیوارهٔ تخمدان.'),
('دیوارهٔ میوه و پوستهٔ دانه','در حالت معمول دیوارهٔ تخمدان به دیوارهٔ میوه و پوشش‌های تخمک به پوستهٔ دانه تبدیل می‌شوند.')],3,'تخمک، تخمدان و تخم منشأهای یکسانی ندارند.')
mcq(11,8,'تکثیر رویشی و تنوع','باغبان از یک گیاه مطلوب چند قلمه تهیه می‌کند. اگر جهش تازه‌ای رخ ندهد، کدام انتظار مناسب‌تر است؟',[
('هر قلمه حتماً نیمی از فام‌تن‌های گیاه مادر را دارد','قلمه‌زنی تولیدمثل رویشی است و با نصف‌شدن مجموعهٔ فام‌تنی همراه نیست.'),
('ژن‌نمود قلمه‌ها مشابه است؛ محیط هم بر رشدشان اثر دارد','تکثیر رویشی بدون آمیزش گامت‌ها معمولاً کلون‌های ژنتیکی می‌سازد؛ یکسانی ژنتیکی مانع اثر محیط نیست.'),
('تنوع قلمه‌ها الزاماً از آرایش مستقل همتاها در میوز ایجاد شده است','قلمه‌زنی مسیر رویشی دارد؛ آرایش همتاها در میوز منشأ معمول تشکیل این افراد نیست.'),
('همهٔ ویژگی‌های ظاهری قلمه‌ها در هر محیط الزاماً دقیقاً یکسان می‌ماند','محیط می‌تواند بر بروز ویژگی‌ها و رشد افراد دارای ژن‌نمود مشابه اثر بگذارد.')],1,'شباهت ژنتیکی را با استقلال از شرایط محیط یکی ندانیم.')

mcq(11,9,'نورگرایی ساقه','ساقهٔ جوان در نور یک‌طرفه به سوی نور خم می‌شود. اگر طول اولیهٔ دو سوی ساقه برابر بوده باشد، کدام تبیین مناسب‌تر است؟',[
('یاخته‌های سمت روشن الزاماً کوتاه شده و می‌میرند','خم‌شدن معمول نتیجهٔ رشد نابرابر است، نه مرگ الزامی یاخته‌های سمت روشن.'),
('نور فقط مانند طناب، ساقه را به‌صورت مکانیکی می‌کشد','نور با تنظیم پاسخ رشد اثر می‌کند، نه با کشیدن مکانیکی ساقه مانند طناب.'),
('رشد طولی بیشتر در سمت سایه باعث خم‌شدن به سمت نور می‌شود','توزیع نامساوی اکسین و رشد طولی بیشتر سمت سایه در ساقهٔ جوان سبب خم‌شدن به سوی نور می‌شود.'),
('برای هر خم‌شدن، ابتدا باید ریشه از خاک خارج شود','پاسخ نورگرایی ساقه نیازمند خروج ریشه از خاک نیست.')],2,'سمت رشد بیشتر در ساقه، سمت مخالف جهت خم‌شدن است.')
mcq(11,9,'چیرگی رأسی','با حذف جوانهٔ رأسی، رشد جوانه‌های جانبی یک ساقه بیشتر می‌شود. کدام نتیجه با نقش اکسین سازگارتر است؟',[
('کاهش اثر بازدارندهٔ رأس می‌تواند فرصت رشد جوانه‌های جانبی را بیشتر کند','اکسین تولیدشده در رأس در چیرگی رأسی نقش دارد؛ برداشتن رأس می‌تواند بازدارندگی رشد جوانه‌های جانبی را کاهش دهد.'),
('رأس تنها محل ممکن تقسیم در سراسر گیاه است','مریستم‌ها و جوانه‌های جانبی نیز توان رشد و تقسیم دارند.'),
('حذف رأس نشان می‌دهد جوانه‌های جانبی فقط با افزایش اکسین رأس رشد می‌کنند','پس از حذف رأس، منبع مهم اکسین رأسی کاهش می‌یابد؛ افزایش رشد جانبی با برداشته‌شدن مهار سازگارتر است.'),
('هر افزایش رشد جانبی ثابت می‌کند تمام هورمون‌های گیاه حذف شده‌اند','حذف رأس همهٔ هورمون‌های گیاه را حذف نمی‌کند؛ تعادل تنظیمی تغییر می‌کند.')],0,'چیرگی رأسی مهار رشد جوانهٔ موجود است، نه نبود جوانه.')
mcq(11,9,'آزمایش هورمون گیاهی','هوای خروجی از محفظهٔ میوهٔ رسیده به دو گروه یکسان میوهٔ نارس حساس می‌رسد. در مسیر گروه دوم، جاذب اختصاصی اتیلن قرار دارد؛ دما و جریان هوا برابر است. اگر گروه دوم دیرتر برسد، کدام نتیجه پشتیبانی می‌شود؟',[
('همهٔ تفاوت رشد الزاماً از دمای دو محفظه است','دما در طرح ثابت نگه داشته شده است؛ تفاوت هدفمند مسیر، حذف اتیلن است.'),
('وجود هر میوهٔ رسیده بدون انتقال هیچ ماده‌ای نتیجه را یکسان می‌کند','تفاوت دو گروه با حذف اتیلن نشان می‌دهد انتقال پیام‌رسان می‌تواند اهمیت داشته باشد.'),
('آزمایش ثابت می‌کند تمام هورمون‌های گیاهی گازند','نتیجه دربارهٔ نقش اتیلن است؛ به حالت فیزیکی همهٔ هورمون‌ها قابل تعمیم نیست.'),
('اتیلن موجود در هوای ورودی در تسریع رسیدن نقش داشته است','با کنترل دما و جریان و تفاوتِ حذف اختصاصی اتیلن، دیررسیدن گروه دوم از نقش اتیلن هوابرد در تسریع رسیدن پشتیبانی می‌کند.')],3,'آزمایش کنترل‌شده نقش یک عامل را می‌آزماید، نه ویژگی همهٔ هورمون‌ها را.')
mcq(11,9,'خشکی و روزنه','در تنش کم‌آبی، افزایش آبسیزیک‌اسید می‌تواند به بسته‌شدن روزنه‌ها کمک کند. کدام هزینهٔ هم‌زمان محتمل است؟',[
('ورود بی‌محدودیت کربن‌دی‌اکسید از روزنهٔ بسته','بسته‌شدن روزنه مسیر ورود کربن‌دی‌اکسید را نیز محدود می‌کند.'),
('کاهش اتلاف آب همراه با محدودشدن ورود CO2','بسته‌شدن روزنه حفظ آب را تقویت می‌کند، اما تبادل گاز و ورود مادهٔ لازم فتوسنتز را نیز کم می‌کند.'),
('افزایش قطعی تعرق به دلیل بسته‌شدن روزنه','بسته‌شدن روزنه معمولاً تعرق روزنه‌ای را کاهش می‌دهد.'),
('بی‌نیازشدن گیاه از هر منبع کربن','گیاه برای ساخت مواد آلی همچنان به منبع کربن نیاز دارد.')],1,'یک پاسخ سازشی می‌تواند هم فایده و هم محدودیت داشته باشد.',tags=['تبادلات گازی','فتوسنتز'])
